import { createHash } from "node:crypto"
import { readFileSync, existsSync } from "node:fs"
import { dirname, resolve, basename } from "node:path"
import { fileURLToPath } from "node:url"

/*
 * Two recorded BK7258 accidents, turned into reflexes.
 *
 * 1. Stale skill-script copies. Thirteen copies of full_flow.sh exist across the
 *    workspace and its worktrees, and their defaults are OPPOSITE: the old one
 *    has OPENVELA_AP=0, so it silently packaged a 66-byte placeholder AP and the
 *    board came up "[AP] CPU1 release failed". The old notify_flash.py has no
 *    auto-injection at all, so a "zero-touch flash" claim made while running it
 *    is false by construction. Reference hashes are NOT hardcoded here (a reading
 *    must not outlive its premise) -- they are computed from the git-tracked copy
 *    in this repository, located relative to this hook file.
 *
 * 2. build.sh resolves board configs through the manifest path under
 *    vendor/beken/boards/..., never through board/bk7258-devkit/configs/...
 *    The latter is valid only for repository-local Python tools.
 */

const SCRIPTS = ["full_flow.sh", "notify_flash.py", "build_worktree.sh"]

// this file: <repo>/.mimocode/hooks/bk7258-guards.ts
const REPO = resolve(dirname(fileURLToPath(import.meta.url)), "..", "..")
const REFERENCE_DIR = resolve(REPO, ".claude/skills/bk7258-worktree-build/scripts")

function sha256(path: string): string | undefined {
  try {
    return createHash("sha256").update(readFileSync(path)).digest("hex")
  } catch {
    return undefined
  }
}

/** Script paths the command actually EXECUTES (not ones it merely reads). */
function executedScripts(command: string): string[] {
  const hits: string[] = []
  // split on shell separators, then look at the head of each segment
  for (const segment of command.split(/(?:\|\||&&|[;|&\n()])/)) {
    const words = segment.trim().split(/\s+/).filter(Boolean)
    if (words.length === 0) continue
    let i = 0
    // step over env assignments and interpreter/launcher prefixes
    while (i < words.length) {
      const w = words[i]
      if (/^[A-Za-z_][A-Za-z0-9_]*=/.test(w)) { i++; continue }
      if (/^(?:bash|sh|python3?|env|sudo|time|exec|nohup|stdbuf|script)$/.test(basename(w))) { i++; continue }
      if (w.startsWith("-")) { i++; continue }
      break
    }
    const head = words[i]
    if (head && SCRIPTS.includes(basename(head))) hits.push(head)
  }
  return hits
}

const hooks = {
  "tool.execute.before": async (input: any, output: any) => {
    if (input.tool !== "bash") return
    const command: string = output.args?.command ?? ""
    if (!command) return

    // --- Guard 1: stale BK7258 skill-script copies -------------------------
    for (const invoked of executedScripts(command)) {
      const name = basename(invoked)
      const reference = resolve(REFERENCE_DIR, name)
      const refHash = sha256(reference)
      if (!refHash) continue // cannot prove anything; stay out of the way

      // The invoked path may be relative; only judge it when it resolves.
      const candidates = [invoked, resolve(REPO, invoked)]
      const actual = candidates.find((p) => existsSync(p))
      if (!actual) continue

      const gotHash = sha256(actual)
      if (gotHash === refHash) continue

      output.cancel = true
      output.cancelReason = [
        `Blocked: ${name} at`,
        `  ${actual}`,
        `differs from the git-tracked copy in this repository:`,
        `  ${reference}`,
        `  invoked sha256 ${gotHash?.slice(0, 12) ?? "unreadable"} vs reference ${refHash.slice(0, 12)}`,
        ``,
        `Stale copies of this skill carry OPPOSITE defaults. The known damage:`,
        `full_flow.sh with OPENVELA_AP=0 packages a 66-byte placeholder AP`,
        `("[AP] CPU1 release failed: -1"), and the old notify_flash.py has no`,
        `auto-injection, so any "zero-touch flash" claim made with it is false.`,
        ``,
        `Run the copy inside the worktree you are building, or the reference path`,
        `above. If the divergence is intentional (you are editing the skill),`,
        `say so and I will re-run with BK7258_SKILL_GUARD=off.`,
      ].join("\n")
      return
    }

    // --- Guard 2: build.sh with a repository-local board config path -------
    if (/(?:^|[\s;&|])(?:\.\/)?build\.sh\s/.test(command) && /(?:^|[\s'"])board\/[^\s'"]*configs\//.test(command)) {
      output.cancel = true
      output.cancelReason = [
        `Blocked: build.sh was given a repository-local board config path`,
        `(board/.../configs/...). build.sh and lunch resolve board configs through`,
        `the manifest path, so this fails with "No config file found at".`,
        ``,
        `Use the mapped path from the parent OpenVela workspace, trailing slash kept:`,
        `  ./build.sh vendor/beken/boards/bk7258/bk7258-devkit/configs/cp/ --cmake -j12`,
        ``,
        `board/... paths are valid only for the repository-local Python tools`,
        `(bk7258-package.sh, the decoder, the packaging tests).`,
      ].join("\n")
      return
    }
  },
}

export default process.env.BK7258_SKILL_GUARD === "off" ? {} : hooks

import { readFileSync, existsSync } from "node:fs"
import { resolve, basename } from "node:path"

/*
 * Three recorded BK7258 accidents, turned into reflexes.
 *
 * 1. full_flow.sh with OPENVELA_AP=0 as its DEFAULT silently packaged a 66-byte
 *    placeholder AP; the board came up "[AP] start: vector bounds check failed
 *    -> ENOEXEC" / "[AP] CPU1 release failed: -1 errno=8". Fixed upstream by
 *    08581cd, which flipped the default to 1 and made --placeholder opt OUT.
 * 2. notify_flash.py without the connect-triggered injector only rings a bell and
 *    prompts for a manual reset. Any "zero-touch flash" claim made while running
 *    it is false by construction.
 * 3. build.sh resolves board configs through the manifest path under
 *    vendor/beken/boards/...; board/bk7258-devkit/configs/... is valid only for
 *    the repository-local Python tools, and fails with "No config file found at".
 *
 * REJECTED APPROACH, recorded so it is not retried: comparing each invoked script
 * against the sha256 of this repository's git-tracked copy. Measured 2026-09-04:
 * 13 copies of full_flow.sh exist across the workspace and its worktrees, in
 * three versions -- 7bdcb499 (workspace root, OPENVELA_AP=0, the actual hazard),
 * 6c920f23 (9 worktrees, already OPENVELA_AP=1, HARMLESS on this axis), and
 * 363b1e32 (team repo + 2 worktrees, adds the image-only --image/--tools-dir
 * mode). Hash inequality would have blocked all 9 harmless copies, and it cannot
 * tell "older" from "newer" -- a hash answers "is this byte-identical to my own
 * copy", not "does this script have the behavior I depend on". The probes below
 * test the behavior instead, and each was baselined on a KNOWN-GOOD file first
 * (good: markers present; stale: zero hits), not only on the bad one.
 */

const GUARDED = new Set(["full_flow.sh", "notify_flash.py"])

/** Script paths the command actually EXECUTES (not ones it merely reads). */
function executedScripts(command: string): string[] {
  const hits: string[] = []
  for (const segment of command.split(/(?:\|\||&&|[;|&\n()])/)) {
    const words = segment.trim().split(/\s+/).filter(Boolean)
    let i = 0
    while (i < words.length) {
      const w = words[i]
      if (/^[A-Za-z_][A-Za-z0-9_]*=/.test(w)) { i++; continue }        // env assignment
      if (/^(?:bash|sh|python3?|env|sudo|time|exec|nohup|stdbuf|script)$/.test(basename(w))) { i++; continue }
      if (w.startsWith("-")) { i++; continue }
      break
    }
    const head = words[i]
    if (head && GUARDED.has(basename(head))) hits.push(head)
  }
  return hits
}

/** Returns a defect description, or undefined when the script carries the behavior. */
function auditScript(name: string, body: string): string | undefined {
  if (name === "full_flow.sh") {
    // Judge the DEFAULT assignment, not the file's identity.
    const m = body.match(/^\s*OPENVELA_AP=(\d)/m)
    if (!m) return `no OPENVELA_AP default found — this is not a recognizable full_flow.sh`
    if (m[1] === "0")
      return [
        `its default is OPENVELA_AP=0, so it packages the bundled 66-byte AP`,
        `placeholder unless --openvela-ap is passed. That image fails CPU1 AP`,
        `release at runtime: "[AP] CPU1 release failed: -1 errno=8".`,
        `Current scripts default to 1 and make --placeholder opt out (08581cd).`,
      ].join("\n")
    return undefined
  }

  if (name === "notify_flash.py") {
    const hasTrigger = body.includes("connect success")
    const hasInjection = body.includes("reboot bootloader")
    if (hasTrigger && hasInjection) return undefined
    return [
      `it has no connect-triggered injector (missing:${hasTrigger ? "" : " 'connect success'"}${hasInjection ? "" : " 'reboot bootloader'"}).`,
      `It can only ring a bell and prompt for a manual reset, so a "zero-touch"`,
      `or "no human needed" flash claim made with it would be false.`,
    ].join("\n")
  }

  return undefined
}

const hooks = {
  "tool.execute.before": async (input: any, output: any) => {
    if (input.tool !== "bash") return
    const command: string = output.args?.command ?? ""
    if (!command) return

    // --- Guard 1+2: skill scripts missing behavior we depend on ------------
    for (const invoked of executedScripts(command)) {
      const name = basename(invoked)
      const path = [invoked, resolve(process.cwd(), invoked)].find((p) => existsSync(p))
      if (!path) continue // cannot read it; stay out of the way rather than guess

      let body: string
      try {
        body = readFileSync(path, "utf-8")
      } catch {
        continue
      }

      const defect = auditScript(name, body)
      if (!defect) continue

      output.cancel = true
      output.cancelReason = [
        `Blocked: ${path}`,
        ``,
        defect,
        ``,
        `Use the copy inside the worktree you are building. If you are deliberately`,
        `running or editing this version, re-run with BK7258_SKILL_GUARD=off.`,
      ].join("\n")
      return
    }

    // --- Guard 3: build.sh with a repository-local board config path -------
    if (/(?:^|[\s;&|])(?:\.\/)?build\.sh\s/.test(command) && /(?:^|[\s'"])board\/[^\s'"]*configs\//.test(command)) {
