// Drives the real tool.execute.before entry point against real files on disk.
import hooks from "/home/czp/openvela_contest/contest2026_272_tokenwujixian/.mimocode/hooks/bk7258-guards.ts"

const WS = "/home/czp/openvela_contest"
const STALE = `${WS}/.claude/skills/bk7258-worktree-build/scripts/full_flow.sh`            // 7bdcb499 AP=0
const GDMA = `${WS}/.worktrees/bk7258-gdma/.claude/skills/bk7258-worktree-build/scripts/full_flow.sh` // AP=1 + stale notifier
const REPO = `${WS}/contest2026_272_tokenwujixian/.claude/skills/bk7258-worktree-build/scripts/full_flow.sh` // both current

type Case = { name: string; command: string; expect: "block" | "pass" }

const cases: Case[] = [
  // guard 1 — the default assignment, not file identity
  { name: "stale workspace-root full_flow (AP=0)", command: `${STALE} --workspace ${WS} --worktree x`, expect: "block" },
  { name: "gdma full_flow, build only (AP=1)", command: `${GDMA} --workspace ${WS} --worktree x --jobs 12`, expect: "pass" },
  { name: "repo full_flow, build only", command: `${REPO} --workspace ${WS} --worktree x --jobs 12`, expect: "pass" },

  // guard 2 — sibling notifier, reached only via --flash
  { name: "gdma full_flow --flash (stale sibling notifier)", command: `${GDMA} --worktree x --flash --device /dev/ttyUSB0`, expect: "block" },
  { name: "repo full_flow --flash (current notifier)", command: `${REPO} --worktree x --flash --device /dev/ttyUSB0`, expect: "pass" },
  { name: "stale notifier invoked directly", command: `python3 ${WS}/.claude/skills/bk7258-worktree-build/scripts/notify_flash.py /dev/ttyUSB0`, expect: "block" },

  // must not fire when the script is only READ, not executed
  { name: "grep of the stale script", command: `grep -n OPENVELA_AP ${STALE}`, expect: "pass" },
  { name: "cat of the stale script", command: `cat ${STALE} | head -40`, expect: "pass" },

  // guard 3 — build.sh board config path
  { name: "build.sh with board/... config", command: `./build.sh board/bk7258-devkit/configs/cp --cmake -j12`, expect: "block" },
  { name: "build.sh with mapped vendor/... config", command: `./build.sh vendor/beken/boards/bk7258/bk7258-devkit/configs/cp/ --cmake -j12`, expect: "pass" },

  // escape hatch + unrelated traffic
  { name: "escape hatch honored", command: `BK7258_SKILL_GUARD=off ${STALE} --worktree x`, expect: "pass" },
  { name: "unrelated command", command: `git status --short`, expect: "pass" },
  { name: "non-bash tool", command: `${STALE}`, expect: "pass" }, // dispatched with tool=read below
]

let failures = 0
for (const c of cases) {
  const out: any = { args: { command: c.command } }
  const tool = c.name === "non-bash tool" ? "read" : "bash"
  await (hooks as any)["tool.execute.before"]({ tool }, out)
  const got = out.cancel ? "block" : "pass"
  const ok = got === c.expect
  if (!ok) failures++
  console.log(`${ok ? "PASS" : "FAIL"}  [want ${c.expect}, got ${got}]  ${c.name}`)
  if (!ok && out.cancelReason) console.log(`      ${out.cancelReason.split("\n")[2] ?? ""}`)
}
console.log(`\n${cases.length - failures}/${cases.length} passed`)

// Show one real rejection message verbatim, to confirm it is actionable.
const demo: any = { args: { command: `${GDMA} --worktree x --flash --device /dev/ttyUSB0` } }
await (hooks as any)["tool.execute.before"]({ tool: "bash" }, demo)
console.log(`\n--- sample rejection ---\n${demo.cancelReason}`)

process.exit(failures === 0 ? 0 : 1)
